{
  "references": [
    {
      "id": "R1",
      "summary_ko": "프롬프트와 달리 인물이 한 장소에만 머무르며 주변 환경과 상호작용하지 않음."
    },
    {
      "id": "R2",
      "summary_ko": "인물이 영상의 절반 가까이 불꽃놀이를 등지고 다른 곳을 쳐다보며 부자연스러움."
    }
  ],
  "candidates": [
    {
      "id": "C1",
      "summary_ko": "배경 불꽃놀이의 스파크가 부자연스럽게 글리치 루프를 일으키며 일관성 없이 변형됨."
    },
    {
      "id": "C2",
      "summary_ko": "여성이 움직일 때 카디건의 무늬가 계속해서 변형되고 재배치됨."
    },
    {
      "id": "C3",
      "summary_ko": "여성이 팔을 올릴 때 손과 재킷 소매가 일관성 없이 형태가 변형됨."
    },
    {
      "id": "C4",
      "summary_ko": "불꽃놀이의 형태와 연기가 약간 불규칙하게 변형되고 터지는 전이를 보임."
    }
  ],
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "인물의 행동 및 상호작용 결여에 대한 설명과 불꽃놀이의 시각적 결함에 대한 설명으로 대상과 결함이 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "인물의 이동 및 상호작용 부재에 대한 설명과 카디건 무늬의 왜곡 현상에 대한 설명으로 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "인물이 주변과 상호작용하지 않는다는 지적과 손 및 소매의 물리적 형태 변형 결함은 서로 다릅니다."
    },
    {
      "reference_id": "R1",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "인물의 행동 및 프롬프트 불일치에 대한 설명과 불꽃놀이 연기 및 형태 왜곡 결함은 대상이 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C1",
      "verdict": "different",
      "reason_ko": "인물의 시선 및 행동의 부자연스러움에 대한 설명과 불꽃놀이의 렌더링 글리치 결함은 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C2",
      "verdict": "different",
      "reason_ko": "인물이 불꽃놀이를 보지 않는다는 지적과 옷 무늬의 변형 결함은 대상과 결함이 완전히 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C3",
      "verdict": "different",
      "reason_ko": "인물의 부자연스러운 시선 방향에 대한 설명과 손/소매의 형태 변형 결함은 서로 다릅니다."
    },
    {
      "reference_id": "R2",
      "candidate_id": "C4",
      "verdict": "different",
      "reason_ko": "인물의 시선 방향 및 상호작용 방식에 대한 설명과 불꽃놀이 자체의 불규칙한 변형 결함은 대상이 다릅니다."
    }
  ]
}
